function n(t){if(t==null||t==="")return null;if(typeof t=="number"&&Number.isFinite(t))return new Date(t<1e10?t*1e3:t);if(typeof t=="string"&&/^\d+$/.test(t.trim())){const r=Number(t.trim());return new Date(r<1e10?r*1e3:r)}const e=new Date(String(t));return Number.isNaN(e.getTime())?null:e}function i(t){const e=n(t);return e?e.toLocaleString():""}function o(t){const e=n(t);return e?e.toLocaleString():"-"}function a(t){const e=n(t);return e?e.toLocaleString("zh-CN",{hour12:!1}):"-"}function m(t){const e=n(t);return e?e.toLocaleString("zh-CN",{month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hour12:!1}):"-"}export{m as a,i as b,o as c,a as f,n as p};
